args.content:
SELECT ?item ?itemLabel ?coords WHERE {
  ?item wdt:P31/wdt:P279* wd:Q1362872 ;
        wdt:P131/wdt:P131* wd:Q8813 ;
        p:P625 ?coordStmt .
  ?coordStmt psv:P625 ?coords .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" . }
}

